   588  exif_mnote_data_olympus_identify_variant (const unsigned char *buf,
   589                  unsigned int buf_size)
   590  {
   591          /* Olympus, Nikon, Sanyo, Epson */
   592          if (buf_size >= 8) {
   593                  /* Match the terminating NUL character, too */
   594                  if (!memcmp (buf, "OLYMPUS", 8))
   595                             return olympusV2;
   596                  else if (!memcmp (buf, "OLYMP", 6))
   597                             return olympusV1;
   598                  else if (!memcmp (buf, "SANYO", 6))
   599                             return sanyoV1;
   600                  else if (!memcmp (buf, "EPSON", 6))
   601                             return epsonV1;
   602                  else if (!memcmp (buf, "Nikon", 6)) {
   603                          switch (buf[6]) {
   604                                  case 1:  return nikonV1;
   605                                  case 2:  return nikonV2;
   606                                  default: return 0; /* Unrecognized Nikon variant */
   607                          }
   608                  }
   609          }
   610
   611          /* Another variant of Nikon */
   612          if ((buf_size >= 2) && (buf[0] == 0x00) && (buf[1] == 0x1b)) {
   613                  return nikonV0;
   614          }
   615
   616          return unrecognized;
   617  }
